    39  /**
    40   * Adds two multiple precision integers, where a >= b.
    41   *
    42   * @param[out] c        - the result.
    43   * @param[in] a         - the first multiple precision integer to add.
    44   * @param[in] b         - the second multiple precision integer to add.
    45   */
    46  static void bn_add_imp(bn_t c, const bn_t a, const bn_t b) {
    47          int max, min;
    48          dig_t carry;
    49
    50          max = a->used;
    51          min = b->used;
    52
    53          /* Grow the result. */
    54          bn_grow(c, max);
    55
    56          if (min == 0) {
    57                  bn_copy(c, a);
    58                  return;
    59          }
    60
    61          if (a->used == b->used) {
    62                  carry = bn_addn_low(c->dp, a->dp, b->dp, max);
    63          } else {
    64                  carry = bn_addn_low(c->dp, a->dp, b->dp, min);
    65                  carry = bn_add1_low(c->dp + min, a->dp + min, carry, max - min);
    66          }
    67          if (carry) {
    68                  bn_grow(c, max + 1);
    69                  c->dp[max] = carry;
    70          }
    71          c->used = max + carry;
    72          bn_trim(c);
    73  }
