    75  /**
    76   * Subtracts two multiple precision integers, where a >= b.
    77   *
    78   * @param[out] c        - the result.
    79   * @param[in] a         - the first multiple precision integer to subtract.
    80   * @param[in] b         - the second multiple precision integer to subtract.
    81   */
    82  static void bn_sub_imp(bn_t c, const bn_t a, const bn_t b) {
    83          int max, min;
    84          dig_t carry;
    85
    86          max = a->used;
    87          min = b->used;
    88
    89          if (min == 0) {
    90                  bn_copy(c, a);
    91                  return;
    92          }
    93
    94          /* Grow the destination to accomodate the result. */
    95          bn_grow(c, max);
    96
    97          if (a->used == b->used) {
    98                  carry = bn_subn_low(c->dp, a->dp, b->dp, min);
    99          } else {
   100                  carry = bn_subn_low(c->dp, a->dp, b->dp, min);
   101                  carry = bn_sub1_low(c->dp + min, a->dp + min, carry, max - min);
   102          }
   103          c->used = max;
   104          bn_trim(c);
   105  }
