   111  void bn_add(bn_t c, const bn_t a, const bn_t b) {
   112          int sa, sb;
   113
   114          sa = a->sign;
   115          sb = b->sign;
   116
   117          if (sa == sb) {
   118                  /* If the signs are equal, copy the sign and add. */
   119                  c->sign = sa;
   120                  if (bn_cmp_abs(a, b) == RLC_LT) {
   121                          bn_add_imp(c, b, a);
   122                  } else {
   123                          bn_add_imp(c, a, b);
   124                  }
   125          } else {
   126                  /* If the signs are different, subtract. */
   127                  if (bn_cmp_abs(a, b) == RLC_LT) {
   128                          bn_sub_imp(c, b, a);
   129                          c->sign = sb;
   130                  } else {
   131                          bn_sub_imp(c, a, b);
   132                          c->sign = sa;
   133                  }
   134          }
   135  }
