   137  void bn_add_dig(bn_t c, const bn_t a, dig_t b) {
   138          dig_t carry;
   139
   140          bn_grow(c, a->used);
   141
   142          if (a->sign == RLC_POS) {
   143                  carry = bn_add1_low(c->dp, a->dp, b, a->used);
   144                  if (carry) {
   145                          bn_grow(c, a->used + 1);
   146                          c->dp[a->used] = carry;
   147                  }
   148                  c->used = a->used + carry;
   149                  c->sign = RLC_POS;
   150          } else {
   151                  /* If a < 0 && |a| >= b, compute c = -(|a| - b). */
