   153                          carry = bn_sub1_low(c->dp, a->dp, b, a->used);
   154                          c->used = a->used;
   155                          c->sign = RLC_NEG;
   156                  } else {
   157                          /* If a < 0 && |a| < b. */
   158                          if (a->used == 1) {
   159                                  c->dp[0] = b - a->dp[0];
   160                          } else {
   161                                  c->dp[0] = b;
   162                          }
   163                          c->used = 1;
   164                          c->sign = RLC_POS;
   165                  }
   166          }
   167          bn_trim(c);
   168  }
