   181                          bn_add_imp(c, b, a);
   182                  } else {
   183                          bn_add_imp(c, a, b);
   184                  }
   185          } else {
   186                  /* If the signs are equal, adjust the sign and subtract. */
   187                  if (bn_cmp_abs(a, b) != RLC_LT) {
   188                          bn_sub_imp(c, a, b);
   189                          c->sign = sa;
   190                  } else {
   191                          bn_sub_imp(c, b, a);
   192                          c->sign = (sa == RLC_POS) ? RLC_NEG : RLC_POS;
   193                  }
   194          }
   195  }
